public decimal Total(Order order)
{
    if (order is null)                       // guard clauses first
        throw new ArgumentNullException(nameof(order));
    if (order.Lines.Count == 0)
        return 0m;

    decimal subtotal = order.Lines.Sum(line => line.Price * line.Quantity);
    return subtotal + order.Shipping;        // one nesting level
}
